<script setup lang="ts">
import {t,locale} from '../i18n'

import { computed,ref,watch,onBeforeUnmount } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { Heart,CalendarDays,BookHeart,MapPin,Check,Plus,Trash2,Stamp,Award,Play,Pause,Dices,Download,Sparkles,Wallet,Backpack,Leaf,Send } from 'lucide-vue-next'
import { api,ApiError,media,type Memory } from '../api'
import { useAlbum } from '../store'
import MemoryMap from '../components/MemoryMap.vue'
const album=useAlbum(),route=useRoute(),router=useRouter(),emit=defineEmits<{open:[memory:Memory]}>()
const tools=[{id:'passport',label:t('城市护照'),icon:Stamp},{id:'badges',label:t('成就勋章'),icon:Award},{id:'replay',label:t('轨迹回放'),icon:Play},{id:'anniversaries',label:t('纪念日'),icon:CalendarDays},{id:'love_notes',label:t('恋爱手账'),icon:BookHeart},{id:'date_plans',label:t('约会计划'),icon:MapPin},{id:'wishes',label:t('甜蜜心愿'),icon:Heart},{id:'love_capsules',label:t('时光胶囊'),icon:Send},{id:'packing_list',label:t('行前清单'),icon:Backpack},{id:'travel_plans',label:t('旅行计划'),icon:CalendarDays},{id:'ingredients',label:t('食材库'),icon:Leaf},{id:'expenses',label:t('花费账本'),icon:Wallet},{id:'food_choices',label:t('今天吃什么'),icon:Dices},{id:'report',label:t('足迹报告'),icon:Award},{id:'poster',label:t('分享海报'),icon:Download},{id:'story',label:t('回忆故事'),icon:Sparkles}]
const active=computed(()=>tools.some(t=>t.id===route.query.tool)?String(route.query.tool):'passport')
interface Entry{id:string;title:string;note:string;date:string;amount:number;done:boolean}
const entries=ref<Entry[]>([]),revision=ref(''),loading=ref(false),busy=ref(false),error=ref(''),title=ref(''),note=ref(''),date=ref(''),amount=ref(0),food=ref(''),story=ref(''),playing=ref(false),step=ref(0)
let timer:ReturnType<typeof setInterval>|undefined,loadVersion=0
const stored=computed(()=>!['passport','badges','replay','report','poster','story'].includes(active.value))
const stamps=computed(()=>{const cities=new Map<string,{name:string;date:string;photos:number;count:number;memory:Memory}>();for(const m of [...album.memories].sort((a,b)=>a.date.localeCompare(b.date))){const name=m.city||m.place;if(!name)continue;const old=cities.get(name);if(old){old.count++;old.photos+=m.photos.length}else cities.set(name,{name,date:m.date,photos:m.photos.length,count:1,memory:m})}return [...cities.values()]})
const badges=computed(()=>[{name:t('第一段故事'),description:t('收藏第一段回忆'),done:album.memories.length>=1},{name:t('快门收藏家'),description:t('收藏 20 张照片'),done:album.photos.length>=20},{name:t('城市漫游者'),description:t('记录 3 个不同地点'),done:stamps.value.length>=3},{name:t('岁月同行'),description:t('在 12 个不同月份留下回忆'),done:new Set(album.memories.map(m=>m.date.slice(0,7))).size>=12},{name:t('浪漫同游人'),description:t('两人加入同一空间'),done:album.members.length>=2},{name:t('寻味搭档'),description:t('记录 5 段美食回忆'),done:album.memories.filter(m=>m.mode==='food').length>=5},{name:t('百张时光'),description:t('珍藏 100 张照片'),done:album.photos.length>=100},{name:t('山海拾遗'),description:t('记录 10 个不同地点'),done:stamps.value.length>=10}])
const routeMemories=computed(()=>[...album.memories].filter(m=>m.latitude!==null&&m.longitude!==null).sort((a,b)=>a.date.localeCompare(b.date)))
const routePhotos=computed(()=>routeMemories.value.slice(0,step.value+1).flatMap(m=>m.photos.slice(0,1).map(p=>({...p,mode:m.mode,memory_id:m.id,memory_title:m.title,latitude:m.latitude,longitude:m.longitude,place:m.place}))))
const totalCost=computed(()=>entries.value.reduce((n,e)=>n+Number(e.amount||0),0))
function days(date:string){const today=new Date();today.setHours(0,0,0,0);const target=new Date(date+'T00:00:00');return Math.round((target.getTime()-today.getTime())/86400000)}
function isLocked(e:Entry){return active.value==='love_capsules'&&!!e.date&&days(e.date)>0}
async function load(){const version=++loadVersion;error.value='';entries.value=[];revision.value='';title.value='';note.value='';date.value='';if(!stored.value)return;loading.value=true;try{const result=await api<{data:Entry[];revision:string}>(`/features/${active.value}`);if(version!==loadVersion)return;entries.value=Array.isArray(result.data)?result.data:[];revision.value=result.revision}catch(e){if(version===loadVersion)error.value=(e as Error).message}finally{if(version===loadVersion)loading.value=false}}
// Refresh shared entries without clearing the draft being typed on this device.
async function syncEntries(){if(!stored.value||busy.value||loading.value)return;const key=active.value,version=loadVersion,before=revision.value;try{const result=await api<{data:Entry[];revision:string}>(`/features/${key}`);if(version!==loadVersion||active.value!==key||busy.value||revision.value!==before)return;if(result.revision!==revision.value){entries.value=Array.isArray(result.data)?result.data:[];revision.value=result.revision}}catch(e){if(version===loadVersion)error.value=(e as Error).message}}
watch(()=>album.revision,syncEntries)

async function persist(next:Entry[]){if(busy.value)return;busy.value=true;error.value='';const key=active.value,version=loadVersion;try{const result=await api<{revision:string}>(`/features/${key}`,{method:'PUT',body:JSON.stringify({data:next,revision:revision.value})});if(key!==active.value||version!==loadVersion)return false;entries.value=next;revision.value=result.revision;return true}catch(e){if(key!==active.value||version!==loadVersion)return false;error.value=(e as Error).message;if(e instanceof ApiError&&e.status===409){busy.value=false;await syncEntries();error.value=t('另一半更新了这份收藏，列表已刷新，你正在填写的内容已保留，请检查后再保存。')}return false}finally{busy.value=false}}
async function add(){if(!title.value.trim())return;if(await persist([...entries.value,{id:crypto.randomUUID(),title:title.value.trim(),note:note.value,date:date.value,amount:amount.value,done:false}])){title.value='';note.value='';date.value='';amount.value=0}}
async function toggle(entry:Entry){await persist(entries.value.map(e=>e.id===entry.id?{...e,done:!e.done}:e))}
function play(){if(playing.value){clearInterval(timer);playing.value=false;return}if(step.value>=routeMemories.value.length-1)step.value=0;playing.value=true;timer=setInterval(()=>{if(step.value>=routeMemories.value.length-1){clearInterval(timer);playing.value=false}else step.value++},1800)}
async function chooseFood(){const choices=[...entries.value.map(e=>e.title),...album.memories.filter(m=>m.mode==='food'&&m.rating>=4).map(m=>m.title)];if(!choices.length){error.value=t('先添加几道菜，或给美食回忆标上四星以上评分。');return};busy.value=true;for(let i=0;i<12;i++){food.value=choices[Math.floor(Math.random()*choices.length)]!;await new Promise(resolve=>setTimeout(resolve,70+i*14))}busy.value=false}
async function generateStory(){busy.value=true;error.value='';try{const result=await api<{story:string;source:string}>('/story',{method:'POST',body:'{}'});story.value=result.story}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function poster(){busy.value=true;error.value='';try{const canvas=document.createElement('canvas');canvas.width=1080;canvas.height=1480;const c=canvas.getContext('2d')!;c.fillStyle='#0b1421';c.fillRect(0,0,1080,1480);c.fillStyle='#5bd3c5';c.font='24px sans-serif';c.fillText('FOOTPRINT · OUR STORY',70,85);c.fillStyle='#eff5fb';c.font='bold 55px sans-serif';c.fillText(t('一起走过，都是故事'),70,185);const photos=album.photos.slice(0,6);for(let i=0;i<photos.length;i++){const img=await new Promise<HTMLImageElement>((resolve,reject)=>{const image=new Image();image.onload=()=>resolve(image);image.onerror=reject;image.src=media(photos[i]!.id)});const x=70+(i%2)*480,y=255+Math.floor(i/2)*315;const ratio=Math.max(450/img.width,280/img.height);c.save();c.beginPath();c.rect(x,y,450,280);c.clip();c.drawImage(img,x+(450-img.width*ratio)/2,y+(280-img.height*ratio)/2,img.width*ratio,img.height*ratio);c.restore()}c.fillStyle='#b9c9d8';c.font='27px sans-serif';c.fillText(t('{0} 段回忆 · {1} 张照片 · {2} 个地点',[album.memories.length,album.photos.length,stamps.value.length]),70,1310);c.font='22px sans-serif';c.fillText(t('把那些舍不得忘记的瞬间，好好收藏。'),70,1380);const link=document.createElement('a');link.download=t('我们的足迹.png');link.href=canvas.toDataURL('image/png');link.click()}catch{error.value=t('海报生成失败，请确认照片可以正常加载。')}finally{busy.value=false}}
watch(active,()=>{clearInterval(timer);playing.value=false;load()},{immediate:true});onBeforeUnmount(()=>{loadVersion++;clearInterval(timer)})
</script>
<template><section class="story-tools"><div class="tools-tabs"><button v-for="tool in tools" :key="tool.id" :class="{active:active===tool.id}" :disabled="busy" @click="router.replace({path:'/tools',query:{tool:tool.id}})"><component :is="tool.icon" :size="17"/>{{tool.label}}</button></div><div class="tools-content glass"><div class="tools-title"><div class="eyebrow">MORE THAN PHOTOGRAPHS</div><h2>{{tools.find(t=>t.id===active)?.label}}</h2></div><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="loading" class="muted">{{t('正在打开共同收藏…')}}</p>
 <div v-if="active==='passport'" class="passport-grid"><button v-for="(stamp,index) in stamps" :key="stamp.name" class="passport-stamp" @click="emit('open',stamp.memory)"><Stamp :size="26"/><span>OUR JOURNEY · {{String(index+1).padStart(3,'0')}}</span><strong>{{stamp.name}}</strong><small>{{t('首次留下足迹 {0}', [stamp.date])}}</small><span>{{t('{0} 段回忆 · {1} 张照片', [stamp.count,stamp.photos])}}</span></button><p v-if="!stamps.length" class="muted">{{t('给回忆填写城市，就能收集这里的城市印章。')}}</p></div>
 <div v-else-if="active==='badges'" class="badges-grid"><div v-for="badge in badges" :key="badge.name" :class="{unlocked:badge.done}"><Award :size="31"/><h3>{{badge.name}}</h3><p>{{badge.description}}</p><span>{{badge.done?t('已点亮'):t('等待一起解锁')}}</span></div></div>
 <div v-else-if="active==='replay'" class="replay-panel"><div class="replay-map"><MemoryMap :photos="routePhotos" :route="routeMemories.slice(0,step+1).map(m=>[m.latitude!,m.longitude!] as [number,number])" @open="photo=>{const m=album.memories.find(m=>m.photos.some(p=>p.id===photo.id));if(m)emit('open',m)}"/></div><div class="replay-controls"><button class="primary" :disabled="routeMemories.length<2" @click="play"><Pause v-if="playing" :size="15"/><Play v-else :size="15"/>{{playing?t('暂停'):t('播放足迹')}}</button><input v-model.number="step" type="range" min="0" :max="Math.max(0,routeMemories.length-1)" :aria-label="t('轨迹播放进度')"><span>{{routeMemories.length?step+1:0}} / {{routeMemories.length}}</span></div><p class="muted small">{{t('{0} {1} · 连线仅表示照片间的时间顺序，不代表实际行走路线。', [routeMemories[step]?.date,routeMemories[step]?.title||t('至少两段带坐标的回忆才能播放。')])}}</p></div>
 <template v-else-if="active==='report'"><div class="report-metrics"><span><strong>{{album.memories.length}}</strong>{{t('段回忆')}}</span><span><strong>{{album.photos.length}}</strong>{{t('张照片')}}</span><span><strong>{{stamps.length}}</strong>{{t('个地点')}}</span><span><strong>{{new Set(album.memories.map(m=>m.date)).size}}</strong>{{t('个记住的日子')}}</span></div><h3>{{t('城市排行')}}</h3><div v-for="stamp in [...stamps].sort((a,b)=>b.count-a.count)" :key="stamp.name" class="report-city"><span>{{stamp.name}}</span><i :style="{width:Math.max(5,stamp.count/Math.max(1,album.memories.length)*100)+'%'}"></i><strong>{{t('{0} 段回忆', [stamp.count])}}</strong></div></template>
 <template v-else-if="active==='poster'"><p class="muted">{{t('将最新六张照片和真实足迹统计生成一张图片，下载后由你决定分享给谁。')}}</p><button class="primary" :disabled="busy||!album.photos.length" @click="poster"><Download :size="16"/>{{busy?t('正在排版…'):t('生成并下载海报')}}</button></template>
 <template v-else-if="active==='story'"><p class="muted">{{t('根据当前空间的真实回忆生成故事。配置模型服务后使用 AI，未配置时生成本地文字草稿。')}}</p><button class="primary" :disabled="busy||!album.memories.length" @click="generateStory"><Sparkles :size="16"/>{{busy?t('正在整理故事…'):t('生成回忆故事')}}</button><p v-if="story" class="story-draft">{{story}}</p></template>
 <template v-else><div v-if="active==='food_choices'" class="food-choice"><Dices :size="37"/><h3>{{food||t('今天，我们吃什么？')}}</h3><button class="primary" :disabled="busy" @click="chooseFood">{{busy?t('挑选中…'):t('帮我们选一道')}}</button><p class="small muted">{{t('从自定义菜品与四星以上的美食回忆中随机选择。')}}</p></div><p v-if="active==='expenses'" class="expense-total">{{t('已记录支出：¥ {0}', [totalCost.toFixed(2)])}}</p>
 <form class="tool-entry-form" @submit.prevent="add"><label>{{active==='love_notes'?t('手账标题'):t('名称')}}<input v-model="title" required maxlength="120" :placeholder="t('写下想一起做的事')"></label><div v-if="['anniversaries','date_plans','travel_plans','love_capsules','expenses'].includes(active)" class="two-col"><label>{{active==='love_capsules'?t('约定打开日期'):t('日期')}}<input v-model="date" type="date" :required="['anniversaries','love_capsules'].includes(active)"></label><label v-if="active==='expenses'">{{t('金额（元）')}}<input v-model.number="amount" type="number" min="0" step="0.01" required></label></div><label v-if="active!=='food_choices'">{{active==='love_capsules'?t('给未来的我们'):t('备注')}}<textarea v-model="note" rows="3" maxlength="5000" :placeholder="t('补充一点细节…')"></textarea></label><button class="primary" :disabled="busy||loading"><Plus :size="15"/>{{busy?t('保存中…'):t('加入我们的收藏')}}</button></form>
 <div class="tool-entries"><article v-for="entry in entries" :key="entry.id" :class="{done:entry.done}"><button class="entry-check" :aria-label="entry.done?t('标为未完成'):t('标为已完成')" :disabled="busy" @click="toggle(entry)"><Check v-if="entry.done" :size="14"/><Heart v-else-if="active==='love_notes'" :size="14"/></button><div><h3>{{entry.title}}</h3><span v-if="entry.date" class="entry-date">{{entry.date}}<span v-if="active==='anniversaries'"> · {{days(entry.date)>=0?t('还有 {0} 天',[days(entry.date)]):t('已过去 {0} 天',[-days(entry.date)])}}</span><span v-if="isLocked(entry)">{{t('· {0} 天后打开', [days(entry.date)])}}</span></span><p v-if="!isLocked(entry)">{{entry.note}}</p><p v-else class="muted">{{t('留给未来的我们，等约定那天再读。')}}</p><span v-if="active==='expenses'">¥ {{Number(entry.amount||0).toFixed(2)}}</span></div><button class="icon danger" :aria-label="t('删除此项')" :disabled="busy" @click="persist(entries.filter(e=>e.id!==entry.id))"><Trash2 :size="14"/></button></article><p v-if="!entries.length&&!loading" class="small muted">{{t('这里还没有记录，写下你们的第一条吧。')}}</p></div></template></div></section></template>
